<section class="page-heading"><div><p class="page-kicker">Transfert <?=e($transfer['transfer_type'])?></p><h2><?=e($transfer['transfer_number'])?></h2><p><?=e($transfer['source_code'].' → '.$transfer['destination_code'].' — '.$transfer['status'])?></p></div></section><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?>
<section class="table-panel"><div class="table-responsive"><table><thead><tr><th>Produit</th><th>Demandé</th><th>Réservé</th><th>Expédié</th><th>Reçu</th><th>Accepté</th><th>Refusé</th></tr></thead><tbody><?php foreach($transfer['items']as$i):?><tr><td><?=e($i['product_name'].' — '.$i['format_name'])?></td><td><?=e($i['requested_bags'])?></td><td><?=e($i['reserved_bags'])?></td><td><?=e($i['shipped_bags'])?></td><td><?=e($i['received_bags'])?></td><td><?=e($i['accepted_bags'])?></td><td><?=e($i['rejected_bags'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="form-panel"><h3>Actions</h3><div class="table-actions"><?php foreach(['draft'=>'submit','submitted'=>'approve','approved'=>'reserve']as$state=>$action):if($transfer['status']===$state):?><form method="post" action="<?=e(base_url('transfers/'.$transfer['id'].'/'.$action))?>"><?=csrf_field()?><button class="btn-primary"><?=e(ucfirst($action))?></button></form><?php endif;endforeach;?></div><?php if(in_array($transfer['status'],['reserved','partially_shipped'],true)):?><form method="post" action="<?=e(base_url('transfers/'.$transfer['id'].'/ship'))?>" class="enterprise-form"><?=csrf_field()?><input name="vehicle_reference" placeholder="Véhicule"><?php foreach($transfer['items']as$i):?><label><span><?=e($i['product_name'])?> à expédier</span><input type="number" min="0" max="<?=e($i['reserved_bags']-$i['shipped_bags'])?>" name="quantity_bags[<?=e($i['id'])?>]"></label><?php endforeach;?><button class="btn-primary">Expédier</button></form><?php endif;?></section>
<?php foreach($transfer['shipments']as$s):if(in_array($s['status'],['dispatched','partially_received'],true)):?><section class="form-panel"><h3>Réception <?=e($s['shipment_number'])?></h3><form method="post" action="<?=e(base_url('transfers/'.$transfer['id'].'/receive'))?>" class="enterprise-form"><?=csrf_field()?><input type="hidden" name="shipment_id" value="<?=e($s['id'])?>"><input type="hidden" name="idempotency_key" value="<?=e(bin2hex(random_bytes(16)))?>"><?php foreach($s['items']as$i):?><label><span><?=e($i['product_name'].' — reste '.($i['quantity_bags']-$i['received_bags']))?></span><input type="number" min="0" name="accepted_bags[<?=e($i['id'])?>]" placeholder="Accepté"><input type="number" min="0" name="rejected_bags[<?=e($i['id'])?>]" placeholder="Refusé"><input name="quality_notes[<?=e($i['id'])?>]" placeholder="Contrôle qualité"></label><?php endforeach;?><button class="btn-primary">Enregistrer réception</button></form></section><?php endif;endforeach;?>
<?php foreach($transfer['returns']as$r):?><section class="form-panel"><h3>Retour <?=e($r['return_number'].' — '.$r['status'])?></h3><?php if($r['status']==='planned'):?><form method="post" action="<?=e(base_url('transfers/'.$transfer['id'].'/returns/'.$r['id'].'/dispatch'))?>"><?=csrf_field()?><button class="btn-primary">Expédier retour</button></form><?php elseif($r['status']==='dispatched'):?><form method="post" action="<?=e(base_url('transfers/'.$transfer['id'].'/returns/'.$r['id'].'/receive'))?>"><?=csrf_field()?><button class="btn-primary">Réceptionner retour source</button></form><?php endif;?></section><?php endforeach;?>
